/**
 * apps/examples/audio_event/audio_event_main.c
 *
 * Audio event detection demo — main entry point.
 *
 * Pipeline: audio capture → MFCC feature extraction → TFLite inference → alert
 *
 * Supports: glass_break, cough (extensible)
 */

#include <nuttx/config.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

#include "audio/audio_capture.h"
#include "dsp/feature_extract.h"
#include "model/event_classifier.h"
#include "alert/event_alert.h"

#define EVENT_NAMES_LEN 16

static const char *event_names[] = {
    "silence",
    "glass_break",
    "cough",
};

static int argmax(const float *probs, int n)
{
    int best = 0;
    for (int i = 1; i < n; i++) {
        if (probs[i] > probs[best]) best = i;
    }
    return best;
}

int main(int argc, char *argv[])
{
    int ret;

    printf("=== Audio Event Detection Demo ===\n");

    /* 1. Init audio capture */
    ret = audio_capture_init();
    if (ret < 0) {
        fprintf(stderr, "ERROR: audio_capture_init failed (%d)\n", ret);
        return -1;
    }

    /* 2. Init feature extraction (MFCC) */
    ret = feature_extract_init();
    if (ret < 0) {
        fprintf(stderr, "ERROR: feature_extract_init failed (%d)\n", ret);
        audio_capture_deinit();
        return -1;
    }

    /* 3. Init TFLite classifier */
    ret = event_classifier_init();
    if (ret < 0) {
        fprintf(stderr, "ERROR: event_classifier_init failed (%d)\n", ret);
        feature_extract_deinit();
        audio_capture_deinit();
        return -1;
    }

    /* 4. Init alert outputs */
    ret = event_alert_init();
    if (ret < 0) {
        fprintf(stderr, "WARN: event_alert_init failed (%d), continuing\n",
                ret);
    }

    printf("Ready. Listening for audio events...\n");

    /* ── Main inference loop ──────────────────────────── */
    for (;;) {
        float frame[MFCC_FRAME_SIZE];      /* raw audio frame */
        float features[MFCC_NUM_COEFFS];   /* MFCC feature vector */
        float probs[EVENT_NAMES_LEN];      /* classification probs */
        int event_id;

        /* Capture one audio frame */
        ret = audio_capture_read(frame, MFCC_FRAME_SIZE);
        if (ret < 0) {
            fprintf(stderr, "ERROR: audio capture read failed (%d)\n", ret);
            usleep(100000);
            continue;
        }

        /* Extract MFCC features */
        ret = feature_extract_compute(frame, MFCC_FRAME_SIZE,
                                      features, MFCC_NUM_COEFFS);
        if (ret < 0) {
            continue;
        }

        /* Run classifier */
        ret = event_classifier_predict(features, MFCC_NUM_COEFFS,
                                       probs, EVENT_NAMES_LEN);
        if (ret < 0) {
            continue;
        }

        /* Get predicted event */
        event_id = argmax(probs, EVENT_NAMES_LEN);

        /* Fire alert on non-silence events */
        if (event_id > 0) {
            printf("[EVENT] %s (prob=%.3f)\n",
                   event_names[event_id], probs[event_id]);

            event_alert_fire(event_id, event_names[event_id],
                             probs[event_id]);
        }
    }

    /* Unreachable in demo */
    event_alert_deinit();
    event_classifier_deinit();
    feature_extract_deinit();
    audio_capture_deinit();
    return 0;
}

