  }
  auto subgraphs = model->subgraphs();
  std::cout << "subgraphs=" << (subgraphs ? subgraphs->size() : 0) << "\n";
  auto sg = subgraphs->Get(0);
  auto tensors = sg->tensors();
  std::cout << "inputs=";
  for (uint32_t i = 0; i < sg->inputs()->size(); ++i) std::cout << (i ? "," : "") << sg->inputs()->Get(i);
  std::cout << "\noutputs=";
  for (uint32_t i = 0; i < sg->outputs()->size(); ++i) std::cout << (i ? "," : "") << sg->outputs()->Get(i);
  std::cout << "\noperators=" << sg->operators()->size() << " tensors=" << tensors->size() << "\n";
  for (uint32_t i = 0; i < tensors->size(); ++i) {
