    for (uint32_t j = 0; j < sg->inputs()->size(); ++j) if ((int)i == sg->inputs()->Get(j)) interesting = true;
    for (uint32_t j = 0; j < sg->outputs()->size(); ++j) if ((int)i == sg->outputs()->Get(j)) interesting = true;
