### 8.2 更新 `event_classifier.c`

集成模型后需要修改 `event_classifier.c` 中的 TODO 部分：

```c
#include "model/event_model_data.h"
#include "tensorflow/lite/micro/micro_interpreter.h"
#include "tensorflow/lite/micro/micro_mutable_op_resolver.h"

static tflite::MicroInterpreter *g_interpreter = nullptr;
static TfLiteTensor *g_input  = nullptr;
static TfLiteTensor *g_output = nullptr;

// Arena: 根据模型大小调整，建议 20-40 KB
static uint8_t g_tensor_arena[32 * 1024];

int event_classifier_init(void)
{
    static const tflite::Model *model = tflite::GetModel(audio_event_int8_tflite);
    if (model->version() != TFLITE_SCHEMA_VERSION) {
        return -1;
    }

    static tflite::MicroMutableOpResolver<8> resolver;
    resolver.AddConv2D();
    resolver.AddDepthwiseConv2D();
    resolver.AddFullyConnected();
    resolver.AddSoftmax();
    resolver.AddReshape();
    resolver.AddAveragePool2D();
    resolver.AddRelu();
    resolver.AddQuantize();  // INT8 量化需要

    static tflite::MicroInterpreter static_interpreter(
        model, resolver, g_tensor_arena, sizeof(g_tensor_arena));
    g_interpreter = &static_interpreter;

    if (g_interpreter->AllocateTensors() != kTfLiteOk) {
        return -1;
    }

    g_input  = g_interpreter->input(0);
    g_output = g_interpreter->output(0);

    printf("[event_classifier] init OK, arena=%zu bytes\n", sizeof(g_tensor_arena));
    return 0;
}

int event_classifier_predict(const float *features, int feat_cnt,
                             float *probs, int num_classes)
{
    // INT8 输入：float → int8 量化
    for (int i = 0; i < feat_cnt; i++) {
        g_input->data.int8[i] = (int8_t)(features[i] / g_input->params.scale
                                         + g_input->params.zero_point);
    }

    if (g_interpreter->Invoke() != kTfLiteOk) {
        return -1;
    }

    // INT8 输出：int8 → float 反量化
    for (int i = 0; i < num_classes; i++) {
        probs[i] = (g_output->data.int8[i] - g_output->params.zero_point)
                   * g_output->params.scale;
    }

    return 0;
}
```

> **归一化参数处理**：训练端的 `mfcc_mean.npy` / `mfcc_std.npy` 需写入固件端，在 `feature_extract_compute()` 输出后、送入模型前做 `(mfcc - mean) / std` 归一化。

