    97	
    98	static FAR struct ap_buffer_s **create_audio_buffers(int fd, int num, int sz)
    99	{
   100	  int i;
   101	  struct audio_buf_desc_s desc;
   102	  FAR struct ap_buffer_s **ret;
   103	
   104	  ret = (FAR struct ap_buffer_s **)calloc(num, sizeof(FAR void *));
   105	
   106	  for (i = 0; i < num; i++)
   107	    {
   108	      desc.numbytes = sz;
   109	      desc.u.pbuffer = &ret[i];
   110	
   111	      ioctl(fd, AUDIOIOC_ALLOCBUFFER, (unsigned long)(uintptr_t)&desc);
