   119	 ****************************************************************************/
   120	
   121	static void free_audio_buffers(FAR struct nxaudio_s *nxaudio)
   122	{
   123	  int x;
   124	  struct audio_buf_desc_s desc;
   125	
   126	  for (x = 0; x < nxaudio->abufnum; x++)
   127	    {
   128	      if (nxaudio->abufs[x] != NULL)
   129	        {
   130	          desc.u.buffer = nxaudio->abufs[x];
