   172	 ****************************************************************************/
   173	
   174	int init_nxaudio_devname(FAR struct nxaudio_s *nxaudio,
   175	                 int fs, int bps, int chnum,
   176	                 const char *devname, const char *mqname)
   177	{
   178	  struct ap_buffer_info_s buf_info;
   179	
   180	  nxaudio->fd = open(devname, O_RDWR | O_CLOEXEC);
   181	  if (nxaudio->fd >= 0)
   182	    {
   183	      if (ioctl(nxaudio->fd, AUDIOIOC_RESERVE, 0) < 0)
   184	        {
   185	          close(nxaudio->fd);
   186	          return -1;
   187	        }
   188	
   189	      /* Audio configuration: set channel num, FS and bps */
   190	
   191	      configure_audio(nxaudio->fd, chnum, fs, bps, 0);
   192	
   193	      nxaudio->chnum = chnum;
   194	
   195	      ioctl(nxaudio->fd, AUDIOIOC_GETBUFFERINFO,
   196	            (unsigned long)(uintptr_t)&buf_info);
   197	
   198	      /* Create message queue to communicate with audio driver */
   199	
   200	      nxaudio->mq = create_audiomq(mqname, nxaudio->fd,
   201	                                   buf_info.nbuffers + 8);
   202	
   203	      /* Create audio buffers to inject audio sample */
   204	
   205	      nxaudio->abufs = create_audio_buffers(nxaudio->fd,
   206	                               buf_info.nbuffers, buf_info.buffer_size);
   207	      nxaudio->abufnum = buf_info.nbuffers;
   208	
   209	      return 0;
   210	    }
   211	  else
   212	    {
   213	      return -1;
   214	    }
   215	}
