   423	/****************************************************************************
   424	 * Name: nxrecorder_enqueuebuffer
   425	 *
   426	 * Description:
   427	 *   Enqueue the audio buffer in the downstream device.  Normally we are
   428	 *   called with a buffer of data to be enqueued in the audio stream.
   429	 *
   430	 *   Be we may also receive an empty length buffer (with only the
   431	 *   AUDIO_APB_FINAL set) in the event of certain write error occurs or in
   432	 *   the event that the file was an exact multiple of the nmaxbytes size of
   433	 *   the audio buffer.
   434	 *   In that latter case, we have an end of file with no bytes written.
   435	 *
   436	 *   These infrequent zero length buffers have to be passed through because
   437	 *   the include the AUDIO_APB_FINAL flag that is needed to terminate the
   438	 *   audio stream.
   439	 *
   440	 ****************************************************************************/
   441	
   442	static int nxrecorder_enqueuebuffer(FAR struct nxrecorder_s *precorder,
   443	                                    FAR struct ap_buffer_s *apb)
   444	{
   445	  struct audio_buf_desc_s bufdesc;
   446	  int ret;
   447	
   448	  /* Now enqueue the buffer with the audio device.  If the number of
   449	   * bytes in the file happens to be an exact multiple of the audio
   450	   * buffer size, then we will receive the last buffer size = 0.  We
   451	   * encode this buffer also so the audio system knows its the end of
   452	   * the file and can do proper clean-up.
   453	   */
   454	
   455	  apb->nbytes = apb->nmaxbytes;
   456	
   457	#ifdef CONFIG_AUDIO_MULTI_SESSION
   458	  bufdesc.session   = precorder->session;
   459	#endif
   460	  bufdesc.numbytes  = apb->nbytes;
   461	  bufdesc.u.buffer = apb;
   462	
   463	  ret = ioctl(precorder->dev_fd, AUDIOIOC_ENQUEUEBUFFER,
   464	              (uintptr_t)&bufdesc);
   465	  if (ret < 0)
   466	    {
   467	      int errcode = errno;
   468	      DEBUGASSERT(errcode > 0);
   469	
   470	      auderr("ERROR: AUDIOIOC_ENQUEUEBUFFER ioctl failed: %d\n", errcode);
   471	      return -errcode;
   472	    }
   473	
   474	  /* Return OK to indicate that we successfully write data to the file
   475	   * (and we are not yet at the end of file)
   476	   */
   477	
   478	  return OK;
   479	}
