/* SPDX-License-Identifier: Apache-2.0 */
#include <cagent/config.h>

#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static char *trim_inplace(char *s)
{
    char *end;

    while (*s && isspace((unsigned char)*s)) {
        s++;
    }

    end = s + strlen(s);
    while (end > s && isspace((unsigned char)end[-1])) {
        *--end = '\0';
    }

    return s;
}

static int load_file(const char *path,
                     agent_config_kv_fn callback,
                     void *user_data)
{
    FILE *fp;
    char line[512];

    if (!path || path[0] == '\0') {
        return AGENT_OK;
    }

    fp = fopen(path, "r");
    if (!fp) {
        return AGENT_OK;
    }

    while (fgets(line, sizeof(line), fp)) {
        char *key;
        char *value;
        char *eq;
        int ret;

        key = trim_inplace(line);
        if (key[0] == '\0' || key[0] == '#') {
            continue;
        }

        eq = strchr(key, '=');
        if (!eq) {
            continue;
        }

        *eq = '\0';
        value = trim_inplace(eq + 1);
        key = trim_inplace(key);

        ret = callback(key, value, user_data);
        if (ret < 0) {
            fclose(fp);
            return ret;
        }
    }

    fclose(fp);
    return AGENT_OK;
}

static void key_to_env_name(const char *prefix,
                            const char *key,
                            char *buf,
                            size_t buf_size)
{
    size_t i;

    i = 0u;

    if (prefix) {
        while (*prefix && i + 1u < buf_size) {
            buf[i++] = *prefix++;
        }
    }

    while (*key && i + 1u < buf_size) {
        if (isalnum((unsigned char)*key)) {
            buf[i++] = (char)toupper((unsigned char)*key);
        } else {
            buf[i++] = '_';
        }
        key++;
    }

    buf[i] = '\0';
}

static int load_env(const char *prefix,
                    agent_config_kv_fn callback,
                    void *user_data)
{
    static const struct {
        const char *key;
    } common_keys[] = {
        { "api_key" },
        { "host" },
        { "path" },
        { "port" },
        { "model" },
        { "timeout_ms" },
    };

    size_t i;

    if (!prefix || prefix[0] == '\0') {
        return AGENT_OK;
    }

    for (i = 0u; i < sizeof(common_keys) / sizeof(common_keys[0]); i++) {
        char env_name[128];
        const char *val;

        key_to_env_name(prefix, common_keys[i].key, env_name, sizeof(env_name));
        val = getenv(env_name);
        if (val && val[0]) {
            int ret = callback(common_keys[i].key, val, user_data);
            if (ret < 0) {
                return ret;
            }
        }
    }

    return AGENT_OK;
}

int agent_config_load(const char *path,
                      const char *env_prefix,
                      agent_config_kv_fn callback,
                      void *user_data)
{
    int ret;

    if (!callback) {
        return AGENT_ERROR_INVALID;
    }

    ret = load_file(path, callback, user_data);
    if (ret < 0) {
        return ret;
    }

    ret = load_env(env_prefix, callback, user_data);
    if (ret < 0) {
        return ret;
    }

    return AGENT_OK;
}
/* SPDX-License-Identifier: Apache-2.0 */
/**
 * cAGENT 配置。
 *
 * 传入 agent_create() 后由核心拷贝，调用者可释放原始 config。
 * 运行时修改应使用 agent_set_limits()，不直接改 agent->config。
 */
#pragma once

#include <cagent/runtime.h>
#include <cagent/types.h>

#ifdef __cplusplus
extern "C" {
#endif

/** limits 默认值初始化器，与 CAGENT_DEFAULT_* 宏对齐 */
#define AGENT_LIMITS_DEFAULT                                           \
    {                                                                  \
        CAGENT_DEFAULT_MAX_STEPS, CAGENT_DEFAULT_TIMEOUT_MS,           \
        CAGENT_DEFAULT_MODEL_TIMEOUT_MS,                               \
        CAGENT_DEFAULT_TOOL_TIMEOUT_MS, 4u,                            \
        CAGENT_DEFAULT_MAX_OUTPUT_TOKENS                               \
    }

typedef struct {
    const char *name;              /* Agent 名称，用于日志标识 */
    const char *system_prompt;     /* 系统提示词，CRITICAL 级不可裁剪 */
    agent_limits_t limits;         /* 运行限制 */
    agent_runtime_t runtime;       /* 平台注入回调，NULL 字段由 fill_defaults 填充 */
    void *user_data;               /* 应用层用户数据，核心不使用 */
} agent_config_t;

/** 生成默认配置：标准 limits + POSIX runtime fallback */
agent_config_t agent_config_default(void);

/** 生成精简配置：小 MCU / bare-metal 适用，更小的 limits */
agent_config_t agent_config_tiny(void);

/**
 * 配置 key-value 回调。
 *
 * agent_config_load 逐行解析配置源，对每个有效 key=value 调用此回调。
 * 回调返回 0 继续解析，返回负值中止解析并传播错误码。
 */
typedef int (*agent_config_kv_fn)(const char *key,
                                  const char *value,
                                  void *user_data);

/**
 * 从 key-value 文本源加载配置。
 *
 * 解析规则：
 *   - 每行格式: key=value
 *   - 行首/行尾空白被 trim
 *   - 空行和 # 开头的行被忽略
 *   - 对每个有效 key=value 调用 callback
 *
 * 典型用法：
 *   agent_config_load("/data/cagent.conf", "CAGENT_", my_kv_handler, &my_cfg);
 *
 * 当 env_prefix 非 NULL 时，解析完文件后还会尝试读取环境变量：
 *   ${env_prefix}API_KEY, ${env_prefix}HOST, ${env_prefix}MODEL 等，
 *   环境变量名大写，key 中的小写转为大写，非字母数字字符转为下划线。
 *   环境变量值会覆盖文件中的同名 key。
 *
 * @param path       配置文件路径，NULL 则跳过文件读取
 * @param env_prefix 环境变量前缀，如 "CAGENT_"，NULL 则跳过环境变量
 * @param callback   key-value 回调，不可为 NULL
 * @param user_data  透传给 callback 的用户数据
 * @return AGENT_OK 或 agent_error_t
 */
int agent_config_load(const char *path,
                      const char *env_prefix,
                      agent_config_kv_fn callback,
                      void *user_data);

#ifdef __cplusplus
}
#endif

