static int enqueue_buffer(struct ap_buffer_s *buffer)
{
  struct audio_buf_desc_s descriptor;

  buffer->curbyte = 0;
  buffer->nbytes = buffer->nmaxbytes;
  buffer->flags = 0;
  memset(&descriptor, 0, sizeof(descriptor));
