   104	
   105	static int es7210_write_reg(struct i2c_master_s *i2c, uint8_t addr,
   106	                            uint32_t frequency, uint8_t reg, uint8_t value)
   107	{
   108	  struct i2c_msg_s msg;
   109	  uint8_t buffer[2];
   110	  int ret;
   111	
   112	  buffer[0] = reg;
   113	  buffer[1] = value;
   114	
   115	  msg.frequency = frequency;
   116	  msg.addr      = addr;
   117	  msg.flags     = 0;
   118	  msg.buffer    = buffer;
   119	  msg.length    = sizeof(buffer);
   120	
   121	  ret = I2C_TRANSFER(i2c, &msg, 1);
   122	  if (ret < 0)
   123	    {
   124	      auderr("ERROR: ES7210 register 0x%02x write failed: %d\n", reg, ret);
   125	    }
   126	
   127	  return ret;
   128	}
   129	
   130	static int es7210_read_reg(struct i2c_master_s *i2c, uint8_t addr,
   131	                           uint32_t frequency, uint8_t reg, uint8_t *value)
   132	{
   133	  struct i2c_msg_s msgs[2];
   134	  int ret;
   135	
   136	  msgs[0].frequency = frequency;
   137	  msgs[0].addr      = addr;
   138	  msgs[0].flags     = I2C_M_NOSTOP;
   139	  msgs[0].buffer    = &reg;
   140	  msgs[0].length    = 1;
   141	
   142	  msgs[1].frequency = frequency;
   143	  msgs[1].addr      = addr;
   144	  msgs[1].flags     = I2C_M_READ;
   145	  msgs[1].buffer    = value;
   146	  msgs[1].length    = 1;
   147	
   148	  ret = I2C_TRANSFER(i2c, msgs, 2);
   149	  if (ret < 0)
   150	    {
   151	      auderr("ERROR: ES7210 register 0x%02x read failed: %d\n", reg, ret);
   152	    }
   153	
   154	  return ret;
   155	}
