   189	static int es7210_configure(struct i2c_master_s *i2c, uint8_t addr,
   190	                            uint32_t frequency)
   191	{
   192	  unsigned int i;
   193	  int ret;
   194	
   195	  ret = es7210_write_reg(i2c, addr, frequency, ES7210_RESET_REG,
   196	                         ES7210_RESET_VALUE);
   197	  if (ret < 0)
   198	    {
   199	      return ret;
   200	    }
   201	
   202	  usleep(5000);
   203	
   204	  for (i = 0; i < sizeof(g_es7210_config) / sizeof(g_es7210_config[0]); i++)
   205	    {
   206	      ret = es7210_write_reg(i2c, addr, frequency,
   207	                             g_es7210_config[i].reg,
   208	                             g_es7210_config[i].value);
   209	      if (ret < 0)
   210	        {
   211	          return ret;
   212	        }
   213	    }
   214	
   215	  printf("[es7210] configured for BOX-3 microphone capture\n");
   216	  es7210_dump_registers(i2c, addr, frequency);
   217	  return OK;
   218	}
